// Obtener número de página del ítem actual
const pagina = $input.item.json.pagina || 1;
const baseUrl = 'https://www.zonaprop.com.ar';

let url;
if (pagina === 1) {
  url = `${baseUrl}/departamentos-venta-capital-federal.html`;
} else {
  url = `${baseUrl}/departamentos-venta-capital-federal-pagina-${pagina}.html`;
}

return [{ json: { pagina, url } }];

const html = $input.item.json.data || '';
const pagina = $input.item.json.pagina || 1;
const baseUrl = 'https://www.zonaprop.com.ar';

const listings = [];

// ── Estrategia 1: JSON embebido __PRELOADED_STATE__ ──────────────────────
const matchState = html.match(/window\.__PRELOADED_STATE__\s*=\s*(\{.*?\});?\s*(?:window\.|<\/script>)/s);
if (matchState) {
  try {
    const state = JSON.parse(matchState[1]);
    // Rutas conocidas donde ZonaProp guarda los listings
    const rutas = [
      ['listStore', 'listings'],
      ['listings', 'results'],
      ['search', 'results', 'listings'],
    ];
    for (const ruta of rutas) {
      let nodo = state;
      try {
        for (const clave of ruta) { nodo = nodo[clave]; }
        if (Array.isArray(nodo) && nodo.length > 0) {
          for (const item of nodo) {
            const urlRel = item.url || item.link || item.seoUrl || '';
            const barrio = (
              item?.postingLocation?.subdivision?.name ||
              item?.location?.subdivision?.name ||
              item?.address?.neighborhood || ''
            ).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '');

            let precioUsd = null;
            const precios = item.prices || (item.price ? [item.price] : []);
            for (const p of precios) {
              if (p && ['USD','US$'].includes((p.currency||'').toUpperCase())) {
                precioUsd = parseFloat(String(p.amount||p.price||'').replace(/\./g,'').replace(',','.')) || null;
                if (precioUsd) break;
              }
            }

            let supM2 = null;
            const attrs = item.mainFeatures || item.features || [];
            for (const a of attrs) {
              const k = (a.id||a.key||'').toLowerCase();
              if (k.includes('total') || k.includes('superficie')) {
                supM2 = parseFloat(String(a.value||'').replace(',','.')) || null;
                if (supM2) break;
              }
            }

            listings.push({
              id: String(item.id || item.listingId || ''),
              url: urlRel.startsWith('/') ? `${baseUrl}${urlRel}` : urlRel,
              titulo: String(item.title || item.name || '').slice(0, 100),
              barrio,
              precio_usd: precioUsd,
              superficie_m2: supM2,
              precio_m2: (precioUsd && supM2 > 0) ? Math.round(precioUsd / supM2) : null,
              ambientes: item.rooms || item.ambientes || null,
              pagina,
            });
          }
          break;
        }
      } catch(e) { continue; }
    }
  } catch(e) { /* JSON inválido, continuar con regex */ }
}

// ── Estrategia 2: regex sobre HTML ─────────────────────────────────────────
if (listings.length === 0) {
  // Buscar data-id en el HTML
  const idMatches = [...html.matchAll(/data-id=["'](\d+)["']/g)];
  const urlMatches = [...html.matchAll(/href=["'](\/[^"']*departamentos[^"']*\.html)["']/g)];
  const precioMatches = [...html.matchAll(/USD\s*([\d\.]+)/gi)];

  for (let i = 0; i < Math.min(idMatches.length, 30); i++) {
    listings.push({
      id: idMatches[i]?.[1] || '',
      url: urlMatches[i] ? `${baseUrl}${urlMatches[i][1]}` : '',
      titulo: '',
      barrio: 'desconocido',
      precio_usd: precioMatches[i] ? parseFloat(precioMatches[i][1].replace(/\./g,'')) : null,
      superficie_m2: null,
      precio_m2: null,
      ambientes: null,
      pagina,
    });
  }
}

console.log(`Página ${pagina}: ${listings.length} listings extraídos`);
return listings.map(l => ({ json: l }));

const items = $input.all();
const fecha = new Date().toISOString().slice(0, 10);

// Agrupar por barrio
const barrios = {};
for (const item of items) {
  const d = item.json;
  if (!d.barrio || d.barrio === 'desconocido') continue;

  if (!barrios[d.barrio]) {
    barrios[d.barrio] = { precios_m2: [], precios_usd: [], listings: [] };
  }

  // Validar precio
  if (d.precio_usd >= 30000 && d.precio_usd <= 5000000) {
    barrios[d.barrio].precios_usd.push(d.precio_usd);
  }
  if (d.precio_m2 >= 500 && d.precio_m2 <= 20000) {
    barrios[d.barrio].precios_m2.push(d.precio_m2);
  }
  barrios[d.barrio].listings.push(d);
}

// Calcular estadísticas
const mediana = (arr) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 === 0 ? (s[m-1] + s[m]) / 2 : s[m];
};
const promedio = (arr) => arr.length ? arr.reduce((a,b) => a+b, 0) / arr.length : null;

const resultado = Object.entries(barrios)
  .map(([barrio, data]) => ({
    barrio,
    stock_avisos: data.listings.length,
    precio_m2_promedio: promedio(data.precios_m2) ? Math.round(promedio(data.precios_m2)) : null,
    precio_m2_mediana: mediana(data.precios_m2) ? Math.round(mediana(data.precios_m2)) : null,
    precio_usd_mediana: mediana(data.precios_usd) ? Math.round(mediana(data.precios_usd)) : null,
    fecha_snapshot: fecha,
  }))
  .sort((a, b) => b.stock_avisos - a.stock_avisos);

console.log(`Barrios con datos: ${resultado.length}`);
console.log(`Total listings: ${items.length}`);
resultado.slice(0, 10).forEach(r => {
  console.log(`  ${r.barrio}: ${r.stock_avisos} avisos | USD ${r.precio_m2_mediana}/m²`);
});

return resultado.map(r => ({ json: r }));
